FILE = "makaveli-at-30.html"
TITLE = "Makaveli at 30: the album 2Pac finished in a week"
TAG = "Flavor Rewind"
H1 = "Makaveli at 30: the album 2Pac finished in a week"
DEK = "Thirty years ago this week, almost two months after he died, the last album Tupac Shakur completed arrived under a new name. It went straight to No. 1."
META = "Flavor Rewind · 6 Nov 2026 · Thirty years on · 4 min read"
LEAD = ("img/mak-coat.jpg", "Tupac Shakur", "@_oldschoolvibes90s_ / Instagram")

BODY = [
("p", "On 5 November 1996, Death Row and Interscope released <em>The Don Killuminati: The 7 Day Theory</em>. The name on the cover wasn't 2Pac. It was Makaveli. Tupac Shakur had been dead for less than two months, and the record most fans simply call <em>Makaveli</em> became the first album released after his death."),
("h2", "August 1996", "Made in ", "one week"),
("p", "The album came together at speed. By most accounts it was written, recorded and mixed in about a week in August 1996. You can hear the hurry in it. It's darker and angrier than <em>All Eyez on Me</em>, the double album he'd put out that February."),
("p", "These were some of the last songs he ever recorded. On 7 September 1996 he was shot in Las Vegas, and he died six days later, on 13 September. He was 25."),
("img", "img/mak-studio.jpg", "Tupac in the studio", "@howsongsarecreated / Instagram"),
("h2", "The name", "Why ", "Makaveli"),
("p", "The alias came from Niccolò Machiavelli, the 16th-century Italian philosopher who wrote <em>The Prince</em>, a book about power and how to hold on to it. For an artist who had spent 1996 in the middle of hip-hop's East Coast–West Coast feud, the choice said a lot about where his head was."),
("p", "The cover went further. It shows Pac painted on a cross. A line printed across the bottom reads: “In no way is this portrait an expression of disrespect for Jesus Christ.”"),
("img", "img/mak-cover.jpg", "The Don Killuminati: The 7 Day Theory (Death Row / Interscope, 1996)"),
("h2", "The release", "Brought ", "forward"),
("p", "The album wasn't meant to come out in 1996 at all. It was planned for March 1997. After Pac's death, Death Row moved the release up by several months, to 5 November."),
("p", "Three singles carried it: “Toss It Up”, “To Live & Die in L.A.” and “Hail Mary”."),
("h2", "The numbers", "Straight in at ", "No. 1"),
("p", "Fans showed up for it. The album debuted at No. 1 on the Billboard 200, selling 664,000 copies in its first week. With <em>All Eyez on Me</em> having also topped the chart that February, it gave Pac two No. 1 albums in the same year. By 1999 <em>Makaveli</em> had been certified four times Platinum in the United States."),
("img", "img/mak-velvet.jpg", "Tupac Shakur", "@2pac_inspiration / Instagram"),
("h2", "Thirty years on", "Still the ", "last word"),
("p", "More albums followed after his death, but those were put together from recordings in the archive. <em>Makaveli</em> is the only posthumous 2Pac album he finished himself, and that's why, for a lot of fans, this is the real last 2Pac album."),
("p", "Thirty years later, it still sounds like what it was: a man in a hurry, saying everything he had left to say."),
]

